/* The guided setup's steps, languages, text and record (pw_setup.h). */
#include "pw_setup.h"

#include <errno.h>
#include <math.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

PwSetupStep pw_setup_start(const PwSetupFacts *facts)
{
    if (!facts->data) return PW_SETUP_NONE;
    if (facts->returning) return facts->prefix ? PW_SETUP_LIMITS : PW_SETUP_PREPARING;
    if (facts->asked || !facts->done) return PW_SETUP_WELCOME;
    if (!facts->runtime) return PW_SETUP_INSTALLING;   /* another build's runtime: the title's own replaces it */
    if (!facts->prefix) return PW_SETUP_PREPARING;
    return PW_SETUP_NONE;
}

PwSetupStep pw_setup_next(PwSetupStep step, const PwSetupFacts *facts)
{
    switch (step) {
    case PW_SETUP_WELCOME: return PW_SETUP_LANGUAGE;
    case PW_SETUP_LANGUAGE: return facts->runtime ? pw_setup_next(PW_SETUP_INSTALLING, facts) : PW_SETUP_INSTALLING;
    /* A set-up console whose runtime was another build's (an updated title folder): the copy alone, then the library */
    case PW_SETUP_INSTALLING:
        return facts->done && !facts->asked && facts->prefix ? PW_SETUP_NONE : facts->prefix ? PW_SETUP_LIMITS : PW_SETUP_PREPARING;
    case PW_SETUP_PREPARING: return PW_SETUP_LIMITS;
    case PW_SETUP_LIMITS: return PW_SETUP_DONE;
    default: return PW_SETUP_NONE;
    }
}

PwSetupStep pw_setup_back(PwSetupStep step)
{
    switch (step) {
    case PW_SETUP_LANGUAGE: return PW_SETUP_WELCOME;
    case PW_SETUP_PREPARING: return PW_SETUP_LANGUAGE;
    default: return PW_SETUP_NONE;
    }
}

float pw_setup_hold(float seconds, int held, float dt)
{
    return held ? seconds + dt : 0.0f;
}

